<template><section class="client-billing-settings"><h2>Billing &amp; insurance settings</h2><ClientInsuranceEditor :client-id="clientId" :agency-id="agencyId" :account-support="accountSupport" start-open /><ClientAccountSupport v-if="accountSupport" :client-id="clientId" :agency-id="agencyId" @manage-contacts="$emit('manage-contacts')" /><details open class="billing-group"><summary>Responsible party and invoices</summary><ResponsibleBillingParty staff :client-id="clientId" :agency-id="agencyId" /><ExternalResponsibleInvoices :client-id="clientId" :agency-id="agencyId" /></details><details class="billing-group"><summary>Self-pay rates</summary><section class="rate-settings"><h3>Client self-pay service overrides</h3><p>Enter the agreed rate for every self-pay service, including when it matches the agency’s standard price. An agency default alone does not complete this client’s billing setup.</p><p v-if="error" role="alert">{{ error }}</p><p v-if="notice" role="status">{{ notice }}</p><ul><li v-for="rate in rates" :key="rate.serviceCode"><button type="button" @click="edit(rate)">{{rate.serviceCode}} · {{ money(rate.amountCents) }} per {{ rate.priceBasis }}</button></li></ul><form @submit.prevent="save"><label>Service code<input v-model="code" required maxlength="32" @input="revision=0" /></label><label>Client’s agreed rate ($)<input v-model="amount" required type="number" min="0.01" step="0.01" /></label><label>Price basis<select v-model="basis"><option value="visit">Per visit</option><option value="unit">Per unit</option></select></label><label>Agreed terms / reason<textarea v-model="reason" required maxlength="2000" /></label><button :disabled="busy">{{busy?'Saving…':'Save client rate override'}}</button></form></section></details></section></template>
<script setup>
import {ref,watch,onBeforeUnmount} from 'vue';import api from '../../services/api';import ClientInsuranceEditor from './ClientInsuranceEditor.vue';import ClientAccountSupport from './ClientAccountSupport.vue';import ResponsibleBillingParty from './ResponsibleBillingParty.vue';import ExternalResponsibleInvoices from './ExternalResponsibleInvoices.vue';
const props=defineProps({clientId:[String,Number],agencyId:[String,Number],accountSupport:Boolean});defineEmits(['manage-contacts']);
const rates=ref([]),code=ref(''),amount=ref(''),basis=ref('visit'),reason=ref(''),revision=ref(0),busy=ref(false),error=ref(''),notice=ref('');let seq=0;
const money=value=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(Number(value)/100);
async function load(){const own=++seq;rates.value=[];code.value='';amount.value='';reason.value='';revision.value=0;error.value='';try{const {data}=await api.get(`/family-billing/account/clients/${props.clientId}/settings`,{params:{agencyId:props.agencyId}});if(own===seq)rates.value=data.rates;}catch(e){if(own===seq)error.value=e.response?.data?.error?.message||'Client billing settings could not be loaded.';}}
function edit(rate){code.value=rate.serviceCode;amount.value=(rate.amountCents/100).toFixed(2);basis.value=rate.priceBasis;revision.value=rate.revision;reason.value='';}
async function save(){if(busy.value)return;const own=seq;busy.value=true;error.value='';notice.value='';try{const {data}=await api.put(`/family-billing/account/clients/${props.clientId}/service-rates/${encodeURIComponent(code.value.trim().toUpperCase())}`,{agencyId:props.agencyId,amountCents:Math.round(Number(amount.value)*100),priceBasis:basis.value,revision:revision.value,reason:reason.value});if(own!==seq)return;rates.value=[...rates.value.filter(rate=>rate.serviceCode!==data.serviceCode),data];edit(data);notice.value='Client service rate saved. Review and sign updated payment terms before collecting.';}catch(e){if(own===seq)error.value=e.response?.data?.error?.message||'The client rate could not be saved.';}finally{busy.value=false;}}
watch(()=>[props.clientId,props.agencyId],load,{immediate:true});onBeforeUnmount(()=>{seq++;});
</script>
<style scoped>.client-billing-settings{display:grid;gap:20px;min-width:0}.billing-group{padding:16px;border:1px solid var(--border,#cddce6);border-radius:10px}.billing-group>summary{font-weight:700;cursor:pointer;padding:4px}.billing-group[open]>summary{margin-bottom:12px}.rate-settings{padding:18px;border:1px solid var(--border,#d5e1ed);border-radius:10px}.rate-settings form{display:grid;gap:12px;max-width:600px}.rate-settings label{display:grid;gap:6px}.rate-settings input,.rate-settings select,.rate-settings textarea{padding:10px;font:inherit;border:1px solid #b6c9dc;border-radius:6px}.rate-settings button{padding:10px;font:inherit}.rate-settings [role=alert]{color:#a12727}</style>
